**1. Return the created reminders too**

Add `RETURNING` to the reminder insert and return both values:

```js
async function createPlantWithReminders(plant) {
  const client = await db.getClient();
  try {
    await client.query('BEGIN');

    const { rows: [dbPlant] } = await client.query(
      'INSERT INTO plants (name) VALUES ($1) RETURNING id',
      [plant.name]
    );

    const reminders = [];
    for (const due of plant.schedule ?? []) {
      const { rows: [r] } = await client.query(
        'INSERT INTO reminders (plant_id, due) VALUES ($1, $2) RETURNING *',
        [dbPlant.id, due]
      );
      reminders.push(r);
    }

    await client.query('COMMIT');
    return { id: dbPlant.id, reminders };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

