**2. Batch insert in one statement**

Build one `VALUES` list with numbered placeholders and pass the values as a flat array. Using `unnest` avoids building the placeholder string by hand and is safe for large arrays:

```js
const schedule = plant.schedule ?? [];
if (schedule.length) {
  const { rows: reminders } = await client.query(
    `INSERT INTO reminders (plant_id, due)
     SELECT $1, d FROM unnest($2::timestamptz[]) AS d
     RETURNING *`,
    [dbPlant.id, schedule]
  );
}
```

This is one round trip with one statement, and it stays inside the same transaction. Replace `timestamptz` with the actual type of your `due` column (`date`, `timestamp`, etc.).

If you prefer the explicit `VALUES` form, which is fine for modest sizes:

```js
const values = [];
const params = [];
schedule.forEach((due, i) => {
  params.push(dbPlant.id, due);
  values.push(`($${i * 2 + 1}, $${i * 2 + 2})`);
});
const { rows: reminders } = await client.query(
  `INSERT INTO reminders (plant_id, due) VALUES ${values.join(', ')} RETURNING *`,
  params
);
```

Keep the batched version inside the same `try` block, before `COMMIT`. Postgres caps a single statement at 65,535 bind parameters, so the `VALUES` form needs chunking for very large schedules. The `unnest` form uses just two parameters no matter how many dates there are, so it avoids that limit.

```js
// plants.js
const db = require('./db');

async function createPlantWithReminders(plant) {
  const client = await db.getClient();
  try {
    await client.query('BEGIN');

    const { rows: [dbPlant] } = await client.query(
      'INSERT INTO plants (name) VALUES ($1) RETURNING id',
      [plant.name]
    );

    const schedule = plant.schedule ?? [];
    let reminders = [];
    if (schedule.length) {
      const { rows } = await client.query(
        `INSERT INTO reminders (plant_id, due)
         SELECT $1, d FROM unnest($2::timestamptz[]) AS d
         RETURNING *`,
        [dbPlant.id, schedule]
      );
      reminders = rows;
    }

    await client.query('COMMIT');
    return { id: dbPlant.id, reminders };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { createPlantWithReminders };
```

