Note: `unnest` expects each element of `schedule` to be a value Postgres can parse as `timestamptz`. ISO 8601 strings like `"2025-06-01T09:00:00Z"` work. If the client sends something else, convert it on the server first, for example with `schedule.map(d => new Date(d).toISOString())`.

The `ORDER BY` inside an `INSERT ... SELECT` doesn't reliably control the order of `RETURNING`. Wrapping the insert in a CTE and ordering the outer `SELECT` by `due` makes the order a guarantee. This sorts chronologically, which matches the input when the schedule is sorted. If you need exact input order even for unsorted schedules, add a position column to `reminders`.

```js
// plants.js
const db = require('./db');

async function createPlantWithReminders(plant, schedule) {
  const client = await db.getClient();
  try {
    await client.query('BEGIN');

    const { rows: [dbPlant] } = await client.query(
      'INSERT INTO plants (name) VALUES ($1) RETURNING id',
      [plant.name]
    );

    let reminders = [];
    if (schedule.length) {
      const { rows } = await client.query(
        `WITH ins AS (
           INSERT INTO reminders (plant_id, due)
           SELECT $1, d FROM unnest($2::timestamptz[]) AS d
           RETURNING *
         )
         SELECT * FROM ins ORDER BY due`,
        [dbPlant.id, schedule]
      );
      reminders = rows;
    }

    await client.query('COMMIT');
    return { id: dbPlant.id, reminders };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { createPlantWithReminders };
```

