```js
// dueInfo.js
const MS_PER_DAY = 86400000;

export function toTimestamp(value) {
  if (value instanceof Date) return value.getTime();
  if (typeof value === 'number') return value;
  if (typeof value === 'string') return Date.parse(value);
  return NaN;
}

export function getDueInfo(nextWaterDate, now = Date.now()) {
  const t = toTimestamp(nextWaterDate);
  if (!Number.isFinite(t)) return { daysLeft: null, overdueBy: null };

  const diffMs = t - now;
  if (diffMs < 0) {
    return { daysLeft: 0, overdueBy: Math.ceil(-diffMs / MS_PER_DAY) };
  }
  return { daysLeft: Math.ceil(diffMs / MS_PER_DAY), overdueBy: null };
