This uses `multer` for multipart parsing and stores files on disk under `UPLOAD_DIR` (defaults to `./uploads`). The photo goes to its own endpoint, `POST /api/plants/:id/photo`, which keeps the plant-creation JSON path unchanged. When the user doesn't pick a new file, the component skips the upload and keeps the existing `photoUrl`.

Install the dependencies first:

```bash
npm i multer
npm i -D supertest
```

**Migration**

```sql
-- up
ALTER TABLE plants ADD COLUMN IF NOT EXISTS photo_url text;

-- down
ALTER TABLE plants DROP COLUMN IF EXISTS photo_url;
```

**Backend: `uploads.js`**

```js
// uploads.js
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const multer = require('multer');

const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(__dirname, 'uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const EXT_BY_TYPE = { 'image/jpeg': '.jpg', 'image/png': '.png' };
const MAX_BYTES = 2 * 1024 * 1024;

const upload = multer({
  storage: multer.diskStorage({
    destination: UPLOAD_DIR,
    // Random server-side name: never trust the client filename.
    filename: (req, file, cb) => cb(null, `${crypto.randomUUID()}${EXT_BY_TYPE[file.mimetype]}`),
  }),
  limits: { fileSize: MAX_BYTES, files: 1 },
  fileFilter: (req, file, cb) => {
    if (!EXT_BY_TYPE[file.mimetype]) {
      return cb(Object.assign(new Error('Only JPG or PNG images are allowed'), { status: 415 }));
    }
    cb(null, true);
  },
});

module.exports = { upload, UPLOAD_DIR };
```

**Backend: route handler (add to `app.js`)**

Export `app` from `app.js` without calling `listen` there, so tests can import it. Put `server.js` (or similar) in charge of `listen`.

```js
// app.js
const express = require('express');
const fs = require('fs');
const db = require('./db');
const { upload, UPLOAD_DIR } = require('./uploads');

const app = express();
app.use(express.json());
app.use('/uploads', express.static(UPLOAD_DIR));

app.post('/api/plants/:id/photo', (req, res, next) => {
  upload.single('photo')(req, res, async (err) => {
    const removeFile = () => req.file && fs.promises.unlink(req.file.path).catch(() => {});

    if (err) {
      const status = err.code === 'LIMIT_FILE_SIZE' ? 413 : err.status || 400;
      return res.status(status).json({ ok: false, error: err.code === 'LIMIT_FILE_SIZE' ? 'Image must be 2MB or smaller' : err.message });
    }
    if (!req.file) return res.status(400).json({ ok: false, error: 'photo file is required' });

    const id = Number(req.params.id);
    if (!Number.isInteger(id)) {
      await removeFile();
      return res.status(400).json({ ok: false, error: 'invalid plant id' });
    }

    try {
      const photoUrl = `/uploads/${req.file.filename}`;
      const { rows: [plant] } = await db.query(
        'UPDATE plants SET photo_url = $1 WHERE id = $2 RETURNING id, name, interval_days, photo_url',
        [photoUrl, id]
      );
      if (!plant) {
        await removeFile();
        return res.status(404).json({ ok: false, error: 'plant not found' });
      }
      res.json({
        ok: true,
        plant: { id: plant.id, name: plant.name, intervalDays: plant.interval_days, photoUrl: plant.photo_url },
      });
    } catch (e) {
      await removeFile();
      next(e);
    }
  });
});

module.exports = app;
```

Multer's `mimetype` comes from the client. For stronger validation, check the file's magic bytes (`FF D8 FF` for JPEG, `89 50 4E 47` for PNG) after upload. That's a short addition if you need it.

**Frontend: `PlantEdit.jsx`**

```jsx
// PlantEdit.jsx
import { useEffect, useState } from 'react';

const ALLOWED_TYPES = ['image/jpeg', 'image/png'];
const MAX_BYTES = 2 * 1024 * 1024;

export default function PlantEdit({ plant, onSaved }) {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(plant.photoUrl ?? null);
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!file) {
      setPreview(plant.photoUrl ?? null);
      return;
    }
    const url = URL.createObjectURL(file);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [file, plant.photoUrl]);

  const handleFile = (e) => {
    const f = e.target.files?.[0];
    setError(null);
    if (!f) return setFile(null);
    if (!ALLOWED_TYPES.includes(f.type)) {
      e.target.value = '';
      return setError('Only JPG or PNG images are allowed');
    }
    if (f.size > MAX_BYTES) {
      e.target.value = '';
      return setError('Image must be 2MB or smaller');
    }
    setFile(f);
  };

  const save = async (e) => {
    e.preventDefault();
    if (!file) return onSaved?.(plant); // no new file: keep existing photoUrl

    setSaving(true);
    setError(null);
    try {
      const body = new FormData();
      body.append('photo', file);
      // Don't set Content-Type manually; the browser adds the multipart boundary.
      const res = await fetch(`/api/plants/${plant.id}/photo`, { method: 'POST', body });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error ?? `Upload failed (${res.status})`);
      setFile(null);
      onSaved?.(data.plant);
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={save}>
      {preview && <img src={preview} alt={`${plant.name} photo preview`} width={120} />}
      <input type="file" accept="image/jpeg,image/png" onChange={handleFile} />
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save'}</button>
    </form>
  );
}
```

Note: `accept="image/*"` was in the requirement, but the validation rejects anything besides JPG and PNG. Narrowing `accept` to match prevents the picker from offering other formats.

**Tests: `photo.test.js`**

```js
// photo.test.js
const fs = require('fs');
const os = require('os');
const path = require('path');

// Set up a temp uploads dir before the app is loaded.
const TMP_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-test-'));
process.env.UPLOAD_DIR = TMP_DIR;

jest.mock('./db', () => ({ query: jest.fn() }));

const request = require('supertest');
const db = require('./db');
const app = require('./app');

// Smallest valid-looking JPEG header; multer doesn't parse content, only type.
const SMALL_JPEG = Buffer.from('ffd8ffe000104a46494600010100000100010000ffd9', 'hex');

beforeEach(() => {
  db.query.mockReset();
  // Echo the photo URL back so the response reflects what was stored.
  db.query.mockImplementation((sql, params) => ({
    rows: [{ id: 1, name: 'Aloe', interval_days: 7, photo_url: params[0] }],
  }));
});

afterAll(() => {
  fs.rmSync(TMP_DIR, { recursive: true, force: true });
});

describe('POST /api/plants/:id/photo', () => {
  test('uploads a small jpeg, returns photoUrl, and writes the file to disk', async () => {
    const res = await request(app)
      .post('/api/plants/1/photo')
      .attach('photo', SMALL_JPEG, { filename: 'aloe.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(200);
    expect(res.body.ok).toBe(true);
    expect(res.body.plant.photoUrl).toMatch(/^\/uploads\/.+\.jpg$/);

    const onDisk = path.join(TMP_DIR, path.basename(res.body.plant.photoUrl));
    expect(fs.existsSync(onDisk)).toBe(true);
  });

  test('rejects a file over 2MB with 413 and stores nothing', async () => {
    const before = fs.readdirSync(TMP_DIR).length;
    const big = Buffer.alloc(2 * 1024 * 1024 + 1, 0xff);

    const res = await request(app)
      .post('/api/plants/1/photo')
      .attach('photo', big, { filename: 'big.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(413);
    expect(res.body.ok).toBe(false);
    expect(fs.readdirSync(TMP_DIR).length).toBe(before);
  });

  test('rejects a non-JPG/PNG type with 415', async () => {
    const res = await request(app)
      .post('/api/plants/1/photo')
      .attach('photo', Buffer.from('GIF89a'), { filename: 'x.gif', contentType: 'image/gif' });

    expect(res.status).toBe(415);
    expect(res.body.ok).toBe(false);
  });

  test('returns 404 for an unknown plant and removes the uploaded file', async () => {
    db.query.mockReset();
    db.query.mockResolvedValueOnce({ rows: [] });
    const before = fs.readdirSync(TMP_DIR).length;

    const res = await request(app)
      .post('/api/plants/999/photo')
      .attach('photo', SMALL_JPEG, { filename: 'aloe.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(404);
    expect(fs.readdirSync(TMP_DIR).length).toBe(before);
  });
});
```

The 404 test relies on the cleanup `unlink` finishing before the response is checked. The handler awaits `removeFile()` before responding, so the directory listing is accurate by the time the assertion runs.

This replaces the separate `POST /api/plants/:id/photo` route with an optional photo on `PUT /api/plants/:id`. JSON-only requests skip multer, and multipart requests can carry text fields plus a file. You can delete the old POST route.

**Backend: `app.js` (replace the POST photo route with this)**

```js
// app.js
const express = require('express');
const fs = require('fs');
const db = require('./db');
const { upload, UPLOAD_DIR } = require('./uploads');

const app = express();
app.use(express.json());
app.use('/uploads', express.static(UPLOAD_DIR));

// Runs multer for multipart requests; for JSON requests it just calls next().
const runUpload = (req, res) =>
  new Promise((resolve, reject) =>
    upload.single('photo')(req, res, err => (err ? reject(err) : resolve()))
  );

app.put('/api/plants/:id', async (req, res, next) => {
  try {
    await runUpload(req, res);
  } catch (err) {
    const tooBig = err.code === 'LIMIT_FILE_SIZE';
    return res.status(tooBig ? 413 : err.status || 400).json({
      ok: false,
      error: tooBig ? 'Image must be 2MB or smaller' : err.message,
    });
  }

  const removeFile = () => req.file && fs.promises.unlink(req.file.path).catch(() => {});
  const fail = async (status, error) => {
    await removeFile();
    return res.status(status).json({ ok: false, error });
  };

  const id = Number(req.params.id);
  if (!Number.isInteger(id)) return fail(400, 'invalid plant id');

  // Multipart fields arrive as strings; JSON fields arrive typed. Handle both.
  const name = req.body?.name;
  const intervalDays = req.body?.intervalDays;

  if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
    return fail(400, 'name must be a non-empty string');
  }
  let interval = null;
  if (intervalDays !== undefined) {
    interval = Number(intervalDays);
    if (!Number.isInteger(interval) || interval < 1 || interval > 365) {
      return fail(400, 'intervalDays must be an integer from 1 to 365');
    }
  }

  const photoUrl = req.file ? `/uploads/${req.file.filename}` : null;

  try {
    // COALESCE keeps the existing value for any field not sent.
    const { rows: [plant] } = await db.query(
      `UPDATE plants
          SET name = COALESCE($2, name),
              interval_days = COALESCE($3, interval_days),
              photo_url = COALESCE($1, photo_url)
        WHERE id = $4
        RETURNING id, name, interval_days, photo_url`,
      [photoUrl, name?.trim() ?? null, interval, id]
    );
    if (!plant) return fail(404, 'plant not found');

    res.json({
      ok: true,
      plant: {
        id: plant.id,
        name: plant.name,
        intervalDays: plant.interval_days,
        photoUrl: plant.photo_url,
      },
    });
  } catch (e) {
    await removeFile();
    next(e);
  }
});

module.exports = app;
```

