Notes:
- The SQL uses `COALESCE`, so a missing field or photo leaves the stored value unchanged. That's why the "no photo" test passes `null` for the photo parameter and the existing photo still comes back.
- Multipart text fields are strings, so `intervalDays: '5'` is converted with `Number()` before validation. JSON numbers pass through the same path.
- Any failure after upload (validation, 404, DB error) deletes the new file, so rejected requests don't leave orphaned images.
- Multer checks only the client-supplied MIME type. Add the magic-byte check if you need stronger validation.

```jsx
// PlantEdit.jsx
import { useEffect, useState } from 'react';

const ALLOWED_TYPES = ['image/jpeg', 'image/png'];
const MAX_BYTES = 2 * 1024 * 1024;

export default function PlantEdit({ plant, onSaved }) {
  const [name, setName] = useState(plant.name ?? '');
  const [intervalDays, setIntervalDays] = useState(plant.intervalDays ?? 7);
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(plant.photoUrl ?? null);
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!file) {
      setPreview(plant.photoUrl ?? null);
      return;
    }
    const url = URL.createObjectURL(file);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [file, plant.photoUrl]);

  const handleFile = (e) => {
    const f = e.target.files?.[0];
    setError(null);
    if (!f) return setFile(null);
    if (!ALLOWED_TYPES.includes(f.type)) {
      e.target.value = '';
      return setError('Only JPG or PNG images are allowed');
    }
    if (f.size > MAX_BYTES) {
      e.target.value = '';
      return setError('Image must be 2MB or smaller');
    }
    setFile(f);
  };

  const save = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError(null);
    try {
      const interval = Number(intervalDays);
      const trimmedName = name.trim();
      if (!trimmedName) throw new Error('Name is required');
      if (!Number.isInteger(interval) || interval < 1 || interval > 365) {
        throw new Error('Interval must be a whole number from 1 to 365');
      }

      let res;
      if (file) {
        // Fields + file: multipart. The browser sets the Content-Type boundary.
        const body = new FormData();
        body.append('name', trimmedName);
        body.append('intervalDays', String(interval));
        body.append('photo', file);
        res = await fetch(`/api/plants/${plant.id}`, { method: 'PUT', body });
      } else {
        // Fields only: JSON.
        res = await fetch(`/api/plants/${plant.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: trimmedName, intervalDays: interval }),
        });
      }

      let data = null;
      try {
        data = await res.json();
      } catch {
        // Non-JSON error body (e.g. proxy or crash page); handled below.
      }
      if (!res.ok || !data?.ok) {
        throw new Error(data?.error ?? `Save failed (${res.status})`);
      }

      setFile(null);
      onSaved?.(data.plant);
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={save}>
      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Plant name"
        required
      />
      <input
        type="number"
        min="1"
        max="365"
        value={intervalDays}
        onChange={(e) => setIntervalDays(e.target.value)}
        required
      />
      <span>days between waterings</span>

      {preview && <img src={preview} alt={`${plant.name} photo preview`} width={120} />}
      <input type="file" accept="image/jpeg,image/png" onChange={handleFile} />

      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save'}</button>
    </form>
  );
}
```

Notes:
- The `PUT` route returns `plant` with camelCase fields (`intervalDays`, `photoUrl`), so `onSaved` receives the same shape the list uses.
- If the server returns a non-JSON error body, the parse fails quietly and the component falls back to `Save failed (status)`.
- The `intervalDays` input stays a string while typing, and conversion happens only on save, so the validation message shows on submit rather than on each keystroke.

