// photo.test.js
const fs = require('fs');
const os = require('os');
const path = require('path');

const TMP_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-test-'));
process.env.UPLOAD_DIR = TMP_DIR;

jest.mock('./db', () => ({ query: jest.fn() }));

const request = require('supertest');
const db = require('./db');
const app = require('./app');

const SMALL_JPEG = Buffer.from('ffd8ffe000104a46494600010100000100010000ffd9', 'hex');
const EXISTING_FILE = 'existing.jpg';
const EXISTING_PHOTO = `/uploads/${EXISTING_FILE}`;
const EXISTING_PATH = path.join(TMP_DIR, EXISTING_FILE);

// Parameters of the UPDATE statement (the SELECT is ignored).
const updateParams = () =>
  db.query.mock.calls.find(([sql]) => sql.trimStart().startsWith('UPDATE'))[1];

beforeEach(() => {
  db.query.mockReset();
  // Recreate the "previous" photo on disk for every test.
  fs.writeFileSync(EXISTING_PATH, SMALL_JPEG);

  db.query.mockImplementation((sql, params) => {
    if (sql.trimStart().startsWith('SELECT')) {
      return { rows: params[0] === 999 ? [] : [{ photo_url: EXISTING_PHOTO }] };
    }
    if (params[3] === 999) return { rows: [] };
    const [photoUrl, name, interval, id, removePhoto] = params;
    return {
      rows: [{
        id,
        name: name ?? 'Aloe',
        interval_days: interval ?? 7,
        photo_url: photoUrl ?? (removePhoto ? null : EXISTING_PHOTO),
      }],
    };
  });
});

afterAll(() => {
  fs.rmSync(TMP_DIR, { recursive: true, force: true });
});

describe('PUT /api/plants/:id', () => {
  test('successful update with photo stores the file, returns photoUrl, and replaces the old file', async () => {
    const res = await request(app)
      .put('/api/plants/1')
      .field('name', 'Aloe Vera')
      .field('intervalDays', '5')
      .attach('photo', SMALL_JPEG, { filename: 'aloe.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(200);
    expect(res.body.ok).toBe(true);
    expect(res.body.plant.name).toBe('Aloe Vera');
    expect(res.body.plant.intervalDays).toBe(5);
    expect(res.body.plant.photoUrl).toMatch(/^\/uploads\/.+\.jpg$/);

    const onDisk = path.join(TMP_DIR, path.basename(res.body.plant.photoUrl));
    expect(fs.existsSync(onDisk)).toBe(true);
    expect(updateParams()[0]).toBe(res.body.plant.photoUrl);
    expect(fs.existsSync(EXISTING_PATH)).toBe(false);
  });

  test('update without photo keeps the existing photoUrl and the file', async () => {
    const res = await request(app)
      .put('/api/plants/1')
      .send({ name: 'Aloe Vera' });

    expect(res.status).toBe(200);
    expect(res.body.plant.name).toBe('Aloe Vera');
    expect(res.body.plant.photoUrl).toBe(EXISTING_PHOTO);
    expect(updateParams()[0]).toBeNull();
    expect(fs.existsSync(EXISTING_PATH)).toBe(true);
  });

  test('removePhoto true (JSON) with name and interval clears photoUrl and deletes the previous file', async () => {
    const res = await request(app)
      .put('/api/plants/1')
      .send({ name: 'Aloe Vera', intervalDays: 5, removePhoto: true });

    expect(res.status).toBe(200);
    expect(res.body.ok).toBe(true);
    expect(res.body.plant.photoUrl).toBeNull();

    const params = updateParams();
    expect(params[0]).toBeNull();          // photoUrl cleared
    expect(params[1]).toBe('Aloe Vera');   // name passed through
    expect(params[2]).toBe(5);             // intervalDays passed through
    expect(params[4]).toBe(true);          // removePhoto flag

    expect(fs.existsSync(EXISTING_PATH)).toBe(false);
  });

  test('new file wins: removePhoto is ignored when a photo is uploaded', async () => {
    const res = await request(app)
      .put('/api/plants/1')
      .field('removePhoto', 'true')
      .attach('photo', SMALL_JPEG, { filename: 'aloe.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(200);
    expect(res.body.plant.photoUrl).toMatch(/^\/uploads\/.+\.jpg$/);
    expect(updateParams()[4]).toBe(false);
  });

  test('rejects a file over 2MB with 413, stores nothing, and changes nothing', async () => {
    const before = fs.readdirSync(TMP_DIR).length;
    const big = Buffer.alloc(2 * 1024 * 1024 + 1, 0xff);

    const res = await request(app)
      .put('/api/plants/1')
      .field('name', 'Aloe Vera')
      .attach('photo', big, { filename: 'big.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(413);
    expect(res.body.ok).toBe(false);
    expect(fs.readdirSync(TMP_DIR).length).toBe(before);
    expect(db.query).not.toHaveBeenCalled();
    expect(fs.existsSync(EXISTING_PATH)).toBe(true);
  });

  test('unknown plant returns 404, removes the uploaded file, and keeps other files', async () => {
    const before = fs.readdirSync(TMP_DIR).length;

    const res = await request(app)
      .put('/api/plants/999')
      .field('name', 'Ghost')
      .attach('photo', SMALL_JPEG, { filename: 'ghost.jpg', contentType: 'image/jpeg' });

    expect(res.status).toBe(404);
    expect(res.body.ok).toBe(false);
    expect(fs.readdirSync(TMP_DIR).length).toBe(before);
    expect(fs.existsSync(EXISTING_PATH)).toBe(true);
  });
});
