Multer's `limits` are fixed when the instance is created, so the 2MB limit has to be set where the instance is built. I moved the multer instance into `app.js` and exported its pieces from `uploads.js`. The route now runs multer as middleware, and an error handler at the end of the file turns multer errors into responses. Because multer fails before the route handler runs, `db.query` is never reached on an oversized upload.

**Backend: `uploads.js`** (exports the storage and filter so `app.js` can set the limits)

```js
// uploads.js
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const multer = require('multer');

const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(__dirname, 'uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const EXT_BY_TYPE = { 'image/jpeg': '.jpg', 'image/png': '.png' };
const MAX_BYTES = 2 * 1024 * 1024;

const storage = multer.diskStorage({
  destination: UPLOAD_DIR,
  // Random server-side name: never trust the client filename.
  filename: (req, file, cb) => cb(null, `${crypto.randomUUID()}${EXT_BY_TYPE[file.mimetype]}`),
});

const fileFilter = (req, file, cb) => {
  if (!EXT_BY_TYPE[file.mimetype]) {
    return cb(Object.assign(new Error('Only JPG or PNG images are allowed'), { status: 415 }));
  }
  cb(null, true);
};

module.exports = { UPLOAD_DIR, MAX_BYTES, storage, fileFilter };
```

**Backend: `app.js`**

```js
// app.js
const express = require('express');
const fs = require('fs');
const path = require('path');
const multer = require('multer');
const db = require('./db');
const { UPLOAD_DIR, MAX_BYTES, storage, fileFilter } = require('./uploads');

const app = express();
app.use(express.json());
app.use('/uploads', express.static(UPLOAD_DIR));

// Multer enforces the size limit while streaming, before any route code runs.
const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 2 * 1024 * 1024, files: 1 },
});

// Deletes a stored upload by its public URL. Only the basename is used,
// so a stored value can't point outside UPLOAD_DIR.
const deleteUpload = async (url) => {
  if (!url) return;
  await fs.promises.unlink(path.join(UPLOAD_DIR, path.basename(url))).catch(() => {});
};

app.put('/api/plants/:id', upload.single('photo'), async (req, res, next) => {
  const removeNewFile = () => req.file && fs.promises.unlink(req.file.path).catch(() => {});
  const fail = async (status, error) => {
    await removeNewFile();
    return res.status(status).json({ ok: false, error });
  };

  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id)) return fail(400, 'invalid plant id');

    // Multipart fields arrive as strings; JSON fields arrive typed. Handle both.
    const name = req.body?.name;
    const intervalDays = req.body?.intervalDays;

    if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
      return fail(400, 'name must be a non-empty string');
    }
    let interval = null;
    if (intervalDays !== undefined) {
      interval = Number(intervalDays);
      if (!Number.isInteger(interval) || interval < 1 || interval > 365) {
        return fail(400, 'intervalDays must be an integer from 1 to 365');
      }
    }

    // A new file always wins: removePhoto is ignored when one is uploaded.
    const photoUrl = req.file ? `/uploads/${req.file.filename}` : null;
    const removeRequested = req.body?.removePhoto === true || req.body?.removePhoto === 'true';
    const removePhoto = !req.file && removeRequested;

    // Read the current photo first so we know which file to delete afterwards.
    const { rows: [before] } = await db.query(
      'SELECT photo_url FROM plants WHERE id = $1',
      [id]
    );
    if (!before) return fail(404, 'plant not found');

    const { rows: [plant] } = await db.query(
      `UPDATE plants
          SET name = COALESCE($2, name),
              interval_days = COALESCE($3, interval_days),
              photo_url = CASE
                WHEN $1::text IS NOT NULL THEN $1::text
                WHEN $5::boolean THEN NULL
                ELSE photo_url
              END
        WHERE id = $4
        RETURNING id, name, interval_days, photo_url`,
      [photoUrl, name?.trim() ?? null, interval, id, removePhoto]
    );
    if (!plant) return fail(404, 'plant not found');

    // Delete the previous file only after the DB update has succeeded.
    const oldUrl = before.photo_url;
    const cleared = removePhoto && oldUrl;
    const replaced = photoUrl && oldUrl && oldUrl !== photoUrl;
    if (cleared || replaced) await deleteUpload(oldUrl);

    res.json({
      ok: true,
      plant: {
        id: plant.id,
        name: plant.name,
        intervalDays: plant.interval_days,
        photoUrl: plant.photo_url,
      },
    });
  } catch (e) {
    await removeNewFile();
    next(e);
  }
});

// Error handler: runs for multer errors and anything passed to next(err).
// Multer fails before the route body runs, so db.query is never called here.
app.use(async (err, req, res, next) => {
  if (req.file?.path) await fs.promises.unlink(req.file.path).catch(() => {});

  if (err instanceof multer.MulterError && err.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({ ok: false, error: 'Image must be 2MB or smaller' });
  }
  if (err.status) {
    return res.status(err.status).json({ ok: false, error: err.message });
  }
  console.error('Unhandled error', err);
  res.status(500).json({ ok: false, error: 'Internal server error' });
});

module.exports = app;
```

Notes:
- The limit is `2 * 1024 * 1024`, the same value `MAX_BYTES` holds in `uploads.js`. `MAX_BYTES` is still exported in case you want to use it in the frontend or elsewhere; the `app.js` limit is written literally to match your request.
- The 415 type error comes from `fileFilter` with `status: 415`. The error handler returns `err.status` for any error that carries one.
- The `try` block now covers the whole route body, so an unexpected throw goes through `removeNewFile` and then to the error handler.
- The existing `photo.test.js` should pass unchanged, since the 413 response and the cleanup behavior are the same.

