The route body should already be skipped when multer raises an error, because Express bypasses non-error handlers after `next(err)`. So the `db.query` call is probably coming from a path where multer didn't report the limit error, or from a `db.query` call that isn't the route's. The app.js below adds defenses so the handler can't reach the database with an oversized file, whichever path happens:

1. A `Content-Length` check that rejects oversized requests before multer reads the body.
2. A wrapper around multer that forwards errors explicitly.
3. A size check on `req.file` inside the handler, before any database call.

```js
// app.js
const express = require('express');
const fs = require('fs');
const path = require('path');
const multer = require('multer');
const db = require('./db');
const { UPLOAD_DIR, storage, fileFilter } = require('./uploads');

const MAX_UPLOAD_BYTES = 2 * 1024 * 1024;

const app = express();
app.use(express.json());
app.use('/uploads', express.static(UPLOAD_DIR));

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: MAX_UPLOAD_BYTES, files: 1 },
});

const unlinkQuietly = (p) => (p ? fs.promises.unlink(p).catch(() => {}) : Promise.resolve());

const tooLarge = () => {
  const err = new Error('Image must be 2MB or smaller');
  err.status = 413;
  return err;
};

// Rejects oversized requests before multer reads the body.
const rejectOversizedRequest = (req, res, next) => {
  const length = Number(req.headers['content-length']);
  if (Number.isFinite(length) && length > MAX_UPLOAD_BYTES + 64 * 1024) {
    return next(tooLarge());
  }
  next();
};

// Wraps multer so every failure goes to the error handler, never to the route.
const runUpload = (req, res, next) =>
  upload.single('photo')(req, res, (err) => (err ? next(err) : next()));

const deleteUpload = async (url) => {
  if (!url) return;
  await unlinkQuietly(path.join(UPLOAD_DIR, path.basename(url)));
};

app.put('/api/plants/:id', rejectOversizedRequest, runUpload, async (req, res, next) => {
  const removeNewFile = () => unlinkQuietly(req.file?.path);
  const fail = async (status, error) => {
    await removeNewFile();
    return res.status(status).json({ ok: false, error });
  };

  try {
    // Defense in depth: multer should have rejected this already.
    if (req.file && req.file.size > MAX_UPLOAD_BYTES) {
      await removeNewFile();
      throw tooLarge();
    }

    const id = Number(req.params.id);
    if (!Number.isInteger(id)) return fail(400, 'invalid plant id');

    const name = req.body?.name;
    const intervalDays = req.body?.intervalDays;

    if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
      return fail(400, 'name must be a non-empty string');
    }
    let interval = null;
    if (intervalDays !== undefined) {
      interval = Number(intervalDays);
      if (!Number.isInteger(interval) || interval < 1 || interval > 365) {
        return fail(400, 'intervalDays must be an integer from 1 to 365');
      }
    }

    // A new file always wins: removePhoto is ignored when one is uploaded.
    const photoUrl = req.file ? `/uploads/${req.file.filename}` : null;
    const removeRequested = req.body?.removePhoto === true || req.body?.removePhoto === 'true';
    const removePhoto = !req.file && removeRequested;

    const { rows: [before] } = await db.query(
      'SELECT photo_url FROM plants WHERE id = $1',
      [id]
    );
    if (!before) return fail(404, 'plant not found');

    const { rows: [plant] } = await db.query(
      `UPDATE plants
          SET name = COALESCE($2, name),
              interval_days = COALESCE($3, interval_days),
              photo_url = CASE
                WHEN $1::text IS NOT NULL THEN $1::text
                WHEN $5::boolean THEN NULL
                ELSE photo_url
              END
        WHERE id = $4
        RETURNING id, name, interval_days, photo_url`,
      [photoUrl, name?.trim() ?? null, interval, id, removePhoto]
    );
    if (!plant) return fail(404, 'plant not found');

    const oldUrl = before.photo_url;
    const cleared = removePhoto && oldUrl;
    const replaced = photoUrl && oldUrl && oldUrl !== photoUrl;
    if (cleared || replaced) await deleteUpload(oldUrl);

    res.json({
      ok: true,
      plant: {
        id: plant.id,
        name: plant.name,
        intervalDays: plant.interval_days,
        photoUrl: plant.photo_url,
      },
    });
  } catch (e) {
    await removeNewFile();
    next(e);
  }
});

// Single error handler for multer errors, explicit errors, and unexpected failures.
app.use(async (err, req, res, next) => {
  await unlinkQuietly(req.file?.path);

  if (err instanceof multer.MulterError && err.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({ ok: false, error: 'Image must be 2MB or smaller' });
  }
  if (err.status) {
    return res.status(err.status).json({ ok: false, error: err.message });
  }
  console.error('Unhandled error', err);
  res.status(500).json({ ok: false, error: 'Internal server error' });
});

module.exports = app;
