const SORTS = {
  // Never-watered plants first (they have no due date), then soonest due.
  next_watering: `
    ORDER BY
      CASE WHEN p.last_watered_at IS NULL THEN 0 ELSE 1 END,
      p.last_watered_at + make_interval(days => p.interval_days) ASC NULLS FIRST,
      p.name ASC`,
  name: `ORDER BY p.name ASC`,
};

app.get('/api/plants', async (req, res, next) => {
  try {
    const orderBy = SORTS[req.query.sort] ?? SORTS.name;

    const { rows } = await db.query(
      `SELECT p.id,
              p.name,
              p.interval_days,
              p.last_watered_at,
              p.photo_url,
              CASE WHEN p.last_watered_at IS NULL THEN NULL
                   ELSE p.last_watered_at + make_interval(days => p.interval_days)
              END AS next_watering_at
         FROM plants p
        ${orderBy}`
    );

    res.json(rows.map(r => ({
      id: r.id,
      name: r.name,
      intervalDays: r.interval_days,
      lastWateredAt: r.last_watered_at ? r.last_watered_at.toISOString() : null,
      nextWateringAt: r.next_watering_at ? r.next_watering_at.toISOString() : null,
      photoUrl: r.photo_url
    })));
  } catch (err) {
    next(err);
  }
});

module.exports = app;
```

Notes:
- `req.query.sort` is looked up in `SORTS`. Any other value, including none, falls back to name order.
- The `CASE` puts never-watered plants (`last_watered_at IS NULL`) in group 0, so they sort ahead of group 1. `NULLS FIRST` on the date expression is redundant for those rows, but it keeps the order explicit.
- `nextWateringAt` is `null` for never-watered plants, which the frontend's `getDueInfo` already treats as "no date".
