Import `theme.css` once in `src/index.js` (`import './theme.css';`), then add this component:

```jsx
// ThemeToggle.jsx
import { useEffect, useState } from 'react';

const KEY = 'theme';

export default function ThemeToggle() {
  const [mode, setMode] = useState(() => localStorage.getItem(KEY) || '');

  useEffect(() => {
    document.body.classList.remove('light', 'dark');
    if (mode) document.body.classList.add(mode);
    if (mode) localStorage.setItem(KEY, mode);
    else localStorage.removeItem(KEY);
  }, [mode]);

  const toggle = () => {
    const systemDark = matchMedia('(prefers-color-scheme: dark)').matches;
    const current = mode || (systemDark ? 'dark' : 'light');
    setMode(current === 'dark' ? 'light' : 'dark');
  };

  return <button type="button" onClick={toggle}>Toggle theme</button>;
}
```

Render `<ThemeToggle />` anywhere in your tree.

**Notes**

- Without a saved choice, the page follows the OS setting through the `:root` media query. The toggle reads the current effective mode first, so the first click always flips what the user sees.
- The `body.light` and `body.dark` blocks repeat the values so an explicit choice wins over the OS setting.
- Persisting the choice is a single `localStorage` key, `theme`.
- For a flash-free load in the plain HTML version, put the saved-class script in `<head>` before the body renders, or use `document.documentElement` for the class.

