Here's the vanilla toggle. It flips `document.documentElement`, updates the visible text and `aria-label`, and saves the choice. It also sets the button's state on load, so the label matches the theme the head script applied.

```html
<button id="theme-toggle" type="button">🌙 Dark</button>

<script>
  (function () {
    const KEY = 'theme';
    const root = document.documentElement;
    const btn = document.getElementById('theme-toggle');

    const isDarkNow = () =>
      root.classList.contains('dark') ||
      (!root.classList.contains('light') &&
        matchMedia('(prefers-color-scheme: dark)').matches);

    const render = () => {
      const dark = isDarkNow();
      btn.textContent = dark ? '☀️ Light' : '🌙 Dark';
      btn.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode');
    };

    btn.addEventListener('click', () => {
      const next = isDarkNow() ? 'light' : 'dark';
      root.classList.remove('light', 'dark');
      root.classList.add(next);
      try { localStorage.setItem(KEY, next); } catch (e) {}
      render();
    });

    render();
  })();
</script>
```

Notes:
- `render()` runs on load, so the label is correct even when the theme came from the OS setting or from the head script.
- The `try` around `localStorage` covers browsers where storage is blocked, such as some private modes.
- Because the head script adds the class to `<html>`, this toggle must also use `documentElement`, as set up above.

