btn.addEventListener('click', (ev) => {
  if (ev.altKey) {
    // Alt+click: forget the saved choice and follow the OS setting again.
    root.classList.remove('light', 'dark');
    try { localStorage.removeItem(KEY); } catch (_) {}
    render();
    return;
