// storage.js
const KEY = 'plants';

function readAll() {
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) ?? '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return []; // corrupt JSON: start fresh rather than crash
  }
}

function writeAll(plants) {
  localStorage.setItem(KEY, JSON.stringify(plants));
}

export async function getPlants() {
  return readAll();
}

export async function savePlant(plant) {
  const plants = readAll();
  const id = plant.id || String(Date.now());
  const saved = { ...plant, id };
  const index = plants.findIndex((p) => String(p.id) === String(id));
  if (index >= 0) plants[index] = saved;
  else plants.push(saved);
  writeAll(plants);
  return saved;
}

export async function deletePlant(id) {
  const plants = readAll();
  const next = plants.filter((p) => String(p.id) !== String(id));
  if (next.length === plants.length) return false;
  writeAll(next);
  return true;
}
```

