Because the functions are `async`, the thrown error becomes a rejected promise, so callers handle it with `try/catch` around `await`.

Here's a minimal `PlantForm.jsx`. I don't have your current file, so it uses a name and interval field. Adjust the fields to match your form. It calls `savePlant`, catches the rejection from `storage.js`, and shows the message inline.

```jsx
// PlantForm.jsx
import { useState } from 'react';
import { savePlant } from './storage';

export default function PlantForm({ onSaved }) {
  const [name, setName] = useState('');
  const [intervalDays, setIntervalDays] = useState(7);
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);

  const onSubmit = async (ev) => {
    ev.preventDefault();
    setError(null);
    setSaving(true);
    try {
      const saved = await savePlant({ name: name.trim(), intervalDays: Number(intervalDays) });
      setName('');
      onSaved?.(saved);
    } catch (err) {
      setError(err.message || 'Could not save plant');
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={onSubmit}>
      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Plant name"
        required
      />
      <input
        type="number"
        min="1"
        max="365"
        value={intervalDays}
        onChange={(e) => setIntervalDays(e.target.value)}
        required
      />
      <button type="submit" disabled={saving}>
        {saving ? 'Saving…' : 'Add plant'}
      </button>
      {error && <p role="alert">{error}</p>}
    </form>
  );
}
```

Notes:
- `role="alert"` on the error message makes screen readers announce it when it appears.
- The error is cleared at the start of each submit, so a stale message doesn't linger after a successful save.
- If you use a different field set, keep the `try/catch` and `setError` pattern. Only the `savePlant({...})` argument changes.

