// storage.js
const KEY = 'plants';

const storageError = (action, err) =>
  new Error(`Could not ${action}: browser storage is unavailable or full (${err?.name ?? 'unknown error'}).`);

export async function loadPlants() {
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) ?? '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return []; // corrupt JSON: recover with an empty list
  }
}

export async function savePlant(plant) {
  const plants = await loadPlants();
  const saved = {
    ...plant,
    id: plant.id ?? crypto.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  };
  const index = plants.findIndex((p) => String(p.id) === String(saved.id));
  if (index >= 0) plants[index] = saved;
  else plants.push(saved);
  try {
    localStorage.setItem(KEY, JSON.stringify(plants));
  } catch (err) {
    throw storageError('save plant', err);
  }
  return saved;
}

export async function deletePlant(id) {
  const plants = await loadPlants();
  const next = plants.filter((p) => String(p.id) !== String(id));
  if (next.length === plants.length) return false;
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch (err) {
    throw storageError('delete plant', err);
  }
  return true;
}

export async function clearPlants() {
  try {
    localStorage.removeItem(KEY);
  } catch (err) {
    throw storageError('clear plants', err);
  }
}
```

Notes:
- `deletePlant` compares ids as strings, so `1` and `'1'` match.
- `deletePlant` returns `false` without writing when nothing matched, so storage isn't touched on a miss.
- Errors from `setItem` and `removeItem` are rethrown with the same helpful message. The async functions turn them into rejections, so callers handle them with `try/catch` around `await`.

