import { useEffect, useState } from 'react';
import { loadPlants, deletePlant, clearPlants } from './storage';

// Insert or replace by id (string/number tolerant).
const upsert = (list, plant) => {
  const i = list.findIndex((p) => String(p.id) === String(plant.id));
  if (i < 0) return [...list, plant];
  const next = list.slice();
  next[i] = plant;
  return next;
};

export default function PlantsList({ savedPlant = null, onChange }) {
  const [plants, setPlants] = useState([]);
  const [status, setStatus] = useState(null);

  // Load on mount.
  useEffect(() => {
    let cancelled = false;
    loadPlants()
      .then((list) => { if (!cancelled) setPlants(list); })
      .catch((err) => { if (!cancelled) setStatus(err.message); });
    return () => { cancelled = true; };
  }, []);

  // Upsert whenever the parent passes a newly saved plant.
  useEffect(() => {
    if (!savedPlant) return;
    setPlants((prev) => upsert(prev, savedPlant));
  }, [savedPlant]);

  // Notify the parent after the local list changes.
  const publish = (next) => {
    setPlants(next);
    onChange?.(next);
  };

  const handleDelete = async (id) => {
    setStatus(null);
    try {
      const next = await deletePlant(id);
      if (next !== null) publish(next); // null = not found; leave state alone
    } catch (err) {
      setStatus(err.message);
    }
  };

  const handleClear = async () => {
    setStatus(null);
    try {
      publish(await clearPlants());
    } catch (err) {
      setStatus(err.message);
    }
  };

  return (
    <div>
      <button type="button" onClick={handleClear} disabled={plants.length === 0}>
        Clear All
      </button>

      {status && <p role="status" aria-live="assertive" aria-atomic="true">{status}</p>}

      <ul>
        {plants.map((p) => (
          <li key={p.id}>
            <strong>{p.name}</strong> — every {p.intervalDays} days{' '}
            <button type="button" onClick={() => handleDelete(p.id)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

Notes:
- The upsert effect doesn't call `onChange`. The parent already knows about the saved plant because it supplied it, so echoing it back would only add a render.
- The upsert only updates local state. If the parent needs the full list after an upsert, call `onChange` from the same place. That would mean a separate effect, and I left it out to keep the component small.
- Passing the same `savedPlant` object twice won't re-run the effect. `savePlant` returns a new object on every call, so saving the same plant again still updates the list.

Your spec passes two different shapes to `onPlantSaved`: a single plant after an upsert, and an array after delete or clear. The parent then has to check `Array.isArray` to tell them apart. That works, but a clearer design would use two callbacks, such as `onPlantSaved` and `onPlantsChange`. The code below follows your spec as written.

The callback is stored in a ref. If the parent passes an inline function, the upsert effect won't re-run on each render, which would otherwise cause a loop.

```jsx
// PlantsList.jsx
import { useEffect, useRef, useState } from 'react';
import { loadPlants, deletePlant, clearPlants } from './storage';

// Insert or replace by id (string/number tolerant).
const upsert = (list, plant) => {
  const i = list.findIndex((p) => String(p.id) === String(plant.id));
  if (i < 0) return [...list, plant];
  const next = list.slice();
  next[i] = plant;
  return next;
};

export default function PlantsList({ savedPlant = null, onPlantSaved }) {
  const [plants, setPlants] = useState([]);
  const [status, setStatus] = useState(null);

  // Keep the latest callback without making the upsert effect depend on it.
  const onPlantSavedRef = useRef(onPlantSaved);
  useEffect(() => {
    onPlantSavedRef.current = onPlantSaved;
  });

  // Load on mount.
  useEffect(() => {
    let cancelled = false;
    loadPlants()
      .then((list) => { if (!cancelled) setPlants(list); })
      .catch((err) => { if (!cancelled) setStatus(err.message); });
    return () => { cancelled = true; };
  }, []);

  // Upsert the saved plant and report it to the parent.
  useEffect(() => {
    if (!savedPlant) return;
    setPlants((prev) => upsert(prev, savedPlant));
    onPlantSavedRef.current?.(savedPlant);
  }, [savedPlant]);

  // Replace the local list and report the full array to the parent.
  const publish = (next) => {
    setPlants(next);
    onPlantSavedRef.current?.(next);
  };

  const handleDelete = async (id) => {
    setStatus(null);
    try {
      const next = await deletePlant(id);
      if (next !== null) publish(next); // null = not found; leave state alone
    } catch (err) {
      setStatus(err.message);
    }
  };

  const handleClear = async () => {
    setStatus(null);
    try {
      publish(await clearPlants());
    } catch (err) {
      setStatus(err.message);
    }
  };

  return (
    <div>
      <button type="button" onClick={handleClear} disabled={plants.length === 0}>
        Clear All
      </button>

      {status && <p role="status" aria-live="assertive" aria-atomic="true">{status}</p>}

      <ul>
        {plants.map((p) => (
          <li key={p.id}>
            <strong>{p.name}</strong> — every {p.intervalDays} days{' '}
            <button type="button" onClick={() => handleDelete(p.id)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
