Notes:
- The parent receives a plant object after an upsert and an array after delete or clear. If you want to avoid the `Array.isArray` check, rename the second callback to something like `onPlantsChange`.
- The parent's `onPlantSaved` gets the same saved object back as `savedPlant`. If it calls `setLastSaved`, React sees the same reference and doesn't re-render, so there's no loop.
- The upsert doesn't run on mount, because `savedPlant` defaults to `null`.

Here's the updated `PlantsList.jsx`. The upsert effect computes the new array from a ref that always holds the latest list, so it can call both callbacks without putting side effects inside a `setState` updater. Under StrictMode, an updater runs twice, which would fire the callbacks twice.

```jsx
// PlantsList.jsx
import { useEffect, useRef, useState } from 'react';
import { loadPlants, deletePlant, clearPlants } from './storage';

// Insert or replace by id (string/number tolerant).
const upsert = (list, plant) => {
  const i = list.findIndex((p) => String(p.id) === String(plant.id));
  if (i < 0) return [...list, plant];
  const next = list.slice();
  next[i] = plant;
  return next;
};

export default function PlantsList({ savedPlant = null, onPlantSaved, onPlantsChange }) {
  const [plants, setPlants] = useState([]);
  const [status, setStatus] = useState(null);

  // Latest list and callbacks, readable from effects and handlers without re-running them.
  const plantsRef = useRef([]);
  const callbacksRef = useRef({ onPlantSaved, onPlantsChange });
  useEffect(() => {
    callbacksRef.current = { onPlantSaved, onPlantsChange };
  });

  // Single place that updates the list, the ref, and the parent's onPlantsChange.
  const commit = (next) => {
    plantsRef.current = next;
    setPlants(next);
    callbacksRef.current.onPlantsChange?.(next);
  };

  // Load on mount.
  useEffect(() => {
    let cancelled = false;
    loadPlants()
      .then((list) => {
        if (cancelled) return;
        plantsRef.current = list;
        setPlants(list);
      })
      .catch((err) => { if (!cancelled) setStatus(err.message); });
    return () => { cancelled = true; };
  }, []);

  // Upsert the incoming saved plant, then notify both callbacks.
  useEffect(() => {
    if (!savedPlant) return;
    commit(upsert(plantsRef.current, savedPlant));
    callbacksRef.current.onPlantSaved?.(savedPlant);
  }, [savedPlant]);

  const handleDelete = async (id) => {
    setStatus(null);
    try {
      const next = await deletePlant(id);
      if (next !== null) commit(next); // null = not found; leave state alone
    } catch (err) {
      setStatus(err.message);
    }
  };

  const handleClear = async () => {
    setStatus(null);
    try {
      commit(await clearPlants());
    } catch (err) {
      setStatus(err.message);
    }
  };

  return (
    <div>
      <button type="button" onClick={handleClear} disabled={plants.length === 0}>
        Clear All
      </button>

      {status && <p role="status" aria-live="assertive" aria-atomic="true">{status}</p>}

      <ul>
        {plants.map((p) => (
          <li key={p.id}>
            <strong>{p.name}</strong> — every {p.intervalDays} days{' '}
            <button type="button" onClick={() => handleDelete(p.id)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
